/* @lc app=leetcode id=956 lang=kotlin */ class Solution { fun tallestBillboard(rods: IntArray): Int = rods.fold(IntArray(10005) { -1 }.apply { this[0] = 0 }) { dp, r -> dp.clone().apply { (0..5000).forEach { d -> if (dp[d] >= 0) this.apply { if (d + r <= 5000) this[d + r] = maxOf(this[d + r], dp[d] + r) }.apply { this[kotlin.math.abs(d - r)] = maxOf(this[kotlin.math.abs(d - r)], dp[d] + maxOf(0, r - d)) } } } }[0] }